/* ---------- drug sheet ---------- */
function field(k, v) { return '<div class="f"><div class="k">' + esc(k) + '</div><div class="v' + (v ? "" : " na") + '">' + (v ? esc(v) : "Not applicable / not routinely used") + '</div></div>'; }
function sec(title, cls, open, rows) { return '<details class="sec ' + (cls || "") + '"' + (open ? " open" : "") + '><summary>' + esc(title) + '</summary><div class="fields">' + (cls === "dose" && DW.id ? doseWarn(DW.id) : "") + rows + '</div></details>'; }
function medSimple(d) {
  if (expoOf(d.id)) return expoSimple(d, "md");
  function F(k, si, fi) { var v = get(d, si, fi); return v ? field(k, v) : ""; }
  function S2(title, cls, rows) { return rows ? sec(title, cls, true, rows) : ""; }
  var rw = (DB.RW || {})[d.id] || {};
  return S2("Indications", "go", F("First-Line Uses", 3, 0) + F("Other Uses", 3, 1) + F("Off-Label", 3, 3)) +
    S2("Contraindications & warnings", "stop", F("Absolute", 4, 0) + F("Relative", 4, 1) + F("Boxed Warning", 5, 1)) +
    S2("Prescribing", "dose", F("Adult Dose", 6, 0) + F("Renal Adjustment", 6, 6) + F("Hepatic Adjustment", 6, 7)) +
    S2("Monitoring", "", F("Labs", 11, 8) + F("ECG", 11, 2) + F("Other", 11, 9)) +
    S2("Adverse effects", "", F("Common", 9, 0) + F("Serious", 9, 1) + F("Life-Threatening", 9, 2)) +
    S2("Special populations", "", F("Pregnancy", 12, 0) + F("Renal Impairment", 12, 4) + F("Hepatic Impairment", 12, 5)) +
    (lang() !== "es" && rw.mp ? S2("Clinical pearl", "", field("On the wards", rw.mp)) : "");
}
function nurseSimple(d) {
  if (expoOf(d.id)) return expoSimple(d, "rn");
  var note = scopeNote(d.id), rw = (DB.RW || {})[d.id] || {};
  function F(k, si, fi) { var v = get(d, si, fi); return v && !/not given by ems|not used by ems/i.test(v) ? field(k, v) : ""; }
  function S2(title, cls, rows) { return rows ? sec(title, cls, true, rows) : ""; }
  return S2("What you are giving it for", "go", F("Used For", 3, 0) + F("Drug Class", 0, 3)) +
    S2("Contraindications and when to hold", "stop", F("Not for people with or taking", 4, 0) + (lang() !== "es" && rw.rh ? field("Hold / notify the provider", rw.rh) : "") + F("Stop if", 14, 4)) +
    S2("Giving it safely", "dose", (note ? field("Your Role", note) : "") + F("Adult Dose", 6, 0) + F("Pediatric Dose", 6, 1) + F("Routes", 7, 0) + F("Rate", 7, 9) + F("Preparation", 7, 10)) +
    S2("Side effects to report", "", F("Common", 9, 0) + F("Report Right Away", 9, 1)) +
    S2("If your client takes it at home", "", F("Suggests", 15, 0) + F("If They Stop It", 15, 4)) +
    S2("Common med errors", "", F("Watch For", 14, 5) + F("Look-Alike / Confused With", 16, 5));
}
/* role wording: drugs nobody "gives" (illicit / unapproved) and drugs EMS does not give */
