  L.ctm = L.ctm || {}; Object.keys(R.ctm || {}).forEach(function (k) { var a = L.ctm[k], b = R.ctm[k]; if (!a || b.n > a.n) L.ctm[k] = b; });
  L.qcat = L.qcat || {}; Object.keys(R.qcat || {}).forEach(function (k) { var a = L.qcat[k], b = R.qcat[k]; if (!a || b.n > a.n) L.qcat[k] = b; });
  Object.keys(R.days).forEach(function (k) { L.days[k] = Math.max(L.days[k] || 0, R.days[k]); });
  Object.keys(R.ach).forEach(function (k) { if (!L.ach[k]) L.ach[k] = R.ach[k]; });
  Object.keys(R.chal || {}).forEach(function (k) { L.chal[k] = L.chal[k] || R.chal[k]; });
  L.owned = (L.owned || []).concat((R.owned || []).filter(function (x) { return (L.owned || []).indexOf(x) < 0; }));
  var avNewer = (R.avatarTs || 0) > (L.avatarTs || 0);
