  if (r.isNew && DB.drugs[r.id]) { Admin.msg = "That ID already exists. Pick another."; return render(); }
  var prev = r.isNew ? null : recordOf(r.id), db = Dex.db;
  var note = r.note || (r.isNew ? "Added medication" : "Edited"); delete r.note; delete r.isNew;
  r.rev = (prev ? prev.rev || 1 : 0) + 1; r.updatedAt = Date.now(); r.updatedBy = Admin.uid || "";
