  first.then(function () { return db.doc("drugdex/" + r.id).set(r); })
    .then(function () { return db.doc("drugdexrev/" + r.id + "~" + r.rev).set({ drugId: r.id, rev: r.rev, ts: r.updatedAt, by: r.updatedBy, note: note, record: r }); })
