    var list = qs.docs.map(function (d) { return d.data(); }).sort(function (x, y) { return y.rev - x.rev; });
    if (!list.some(function (x) { return x.rev === 1; })) list.push({ drugId: id, rev: 1, ts: SEED_TS, note: "Original DrugDex entry", record: null, seed: true });
