  c += '<label class="afield">Question asked (optional)<input class="pinput" data-s="ask" value="' + esc(s.ask || "") + '"></label>';
  c += keyInputs("correct", s.correct) + keyInputs("ok", s.ok) + keyInputs("wrong", s.wrong);
  c += '<label class="afield">Why (the teaching point)<textarea class="pinput" rows="3" data-s="why">' + esc(s.why || "") + '</textarea></label>';
  c += '<label class="afield">Drug notes (one per line, as drug-id: note)<textarea class="pinput" rows="4" data-s="notes">' + esc(Object.keys(s.notes || {}).map(function (k) { return k + ": " + s.notes[k]; }).join("\n")) + '</textarea></label>';
  c += '<label class="chk"><input type="checkbox" data-s="pub"' + (s.hidden ? "" : " checked") + '> Published</label></fieldset>';
  return c + '<div class="actions"><button class="btn" data-aact="saves"' + (Dex.db && !Admin.busy ? "" : " disabled") + '>Save scenario</button><button class="btn ghost" data-aact="sback">Cancel</button></div></div>';
