  s.rev = (s0.rev || 1) + (s0.isNew ? 0 : 1); s.updatedAt = Date.now(); s.by = Admin.uid || "";
  if (Admin.busy) return; var ref = Dex.db.doc("scenbank/" + s.id); Admin.busy = true;
