/* moods: happy (default), joy, sad, think + easter eggs */
var FACES = [
  ["happy", "Happy", 0], ["joy", "Overjoyed", 0], ["sad", "Bummed", 0], ["think", "Thinking", 0],
  ["wink", "Wink", 1], ["star", "Starstruck", 1], ["heart", "Heart eyes", 1], ["dizzy", "Dizzy", 1], ["sleepy", "Sleepy", 1], ["silly", "Silly", 1], ["shock", "Shocked", 1], ["smug", "Smug", 1],
  ["determined", "Determined", 0, 300], ["angel", "Angelic", 0, 400], ["goofy", "Goofy", 0, 500], ["cool", "Too Cool", 0, 700]
];
function bugFace(y, mood, b, faceItem) {
  var mc = b.smile || "#fff", cool = b.eyes === "cool" && !faceItem, s = "";
  function E() {
    if (b.eyes === "glow" && !faceItem) { var g = b.glow || "#22d3ee"; return [88, 112].map(function (x) { return '<ellipse cx="' + x + '" cy="' + y + '" rx="12" ry="11" fill="' + g + '" opacity=".28"/><ellipse cx="' + x + '" cy="' + y + '" rx="9" ry="8" fill="' + g + '"/><ellipse cx="' + x + '" cy="' + y + '" rx="2.2" ry="6.5" fill="#05030a"/><circle cx="' + (x + 3) + '" cy="' + (y - 3) + '" r="1.6" fill="#fff"/>'; }).join(""); }
    return eyeBall(88, y, 9) + eyeBall(112, y, 9);
  }
  switch (mood) {
    case "joy": s = (cool ? shades(y) : arcEye(88, y + 2, true) + arcEye(112, y + 2, true)) + mouth("grin", y + 13, mc) + '<circle cx="78" cy="' + (y + 12) + '" r="4" fill="#ff8fa3" opacity=".7"/><circle cx="122" cy="' + (y + 12) + '" r="4" fill="#ff8fa3" opacity=".7"/>'; break;
    case "sad": s = (cool ? shades(y) : eyeBall(88, y + 1, 9, 0, 3) + eyeBall(112, y + 1, 9, 0, 3) + '<path d="M78 ' + (y - 14) + ' L94 ' + (y - 10) + ' M122 ' + (y - 14) + ' L106 ' + (y - 10) + '" stroke="' + INK + '" stroke-width="3" stroke-linecap="round"/>') + mouth("frown", y + 15, mc) + '<path d="M80 ' + (y + 8) + ' q-4 8 0 10 q4 -2 0 -10z" fill="#7dd3fc"/>'; break;
    case "think": s = (cool ? shades(y) : eyeBall(88, y, 9, 3, -2) + eyeBall(112, y, 9, 3, -2) + '<path d="M104 ' + (y - 16) + ' Q112 ' + (y - 21) + ' 122 ' + (y - 15) + '" stroke="' + INK + '" stroke-width="3" fill="none" stroke-linecap="round"/>') + mouth("flat", y + 15, mc); break;
    case "wink": s = (cool ? shades(y) : arcEye(88, y + 1, true) + eyeBall(112, y, 9)) + mouth("smile", y + 15, mc); break;
    case "star": s = starShape(88, y, 12, "#ffd84a") + starShape(112, y, 12, "#ffd84a") + mouth("grin", y + 14, mc); break;
    case "heart": s = heartShape(88, y, 9, "#ff4d6d") + heartShape(112, y, 9, "#ff4d6d") + mouth("smile", y + 15, mc); break;
    case "dizzy": s = ['88', '112'].map(function (x) { x = +x; return '<circle cx="' + x + '" cy="' + y + '" r="9" fill="#fff"/><path d="M' + x + ' ' + y + ' m-2 0 a2 2 0 1 1 4 0 a4 4 0 1 1 -8 0 a6 6 0 1 1 12 0" stroke="' + INK + '" stroke-width="2" fill="none"/>'; }).join("") + mouth("o", y + 13, mc) + '<g fill="#ffd84a">' + starShape(70, y - 34, 6, "#ffd84a") + starShape(130, y - 38, 5, "#ffd84a") + '</g>'; break;
    case "sleepy": s = '<path d="M80 ' + (y + 1) + ' H96 M104 ' + (y + 1) + ' H120" stroke="' + INK + '" stroke-width="3.5" stroke-linecap="round"/>' + mouth("o", y + 13, mc) + '<text x="128" y="' + (y - 24) + '" font-size="16" font-weight="800" fill="#8b9bd8" font-family="sans-serif">z</text><text x="140" y="' + (y - 38) + '" font-size="12" font-weight="800" fill="#8b9bd8" font-family="sans-serif">z</text>'; break;
    case "silly": s = eyeBall(88, y, 11, -2, 2) + eyeBall(112, y, 7, 3, -1) + mouth("tongue", y + 15, mc); break;
    case "shock": s = eyeBall(88, y - 1, 11, 0, 0) + eyeBall(112, y - 1, 11, 0, 0) + mouth("o", y + 15, mc); break;
    case "determined": s = eyeBall(88, y + 1, 9, 1, 1) + eyeBall(112, y + 1, 9, -1, 1) + '<path d="M77 ' + (y - 15) + ' L96 ' + (y - 9) + ' M123 ' + (y - 15) + ' L104 ' + (y - 9) + '" stroke="' + INK + '" stroke-width="4" stroke-linecap="round"/>' + '<path d="M91 ' + (y + 16) + ' Q100 ' + (y + 19) + ' 109 ' + (y + 15) + '" stroke="' + mc + '" stroke-width="3.5" fill="none" stroke-linecap="round"/>'; break;
    case "angel": s = arcEye(88, y, false) + arcEye(112, y, false) + mouth("smile", y + 15, mc) + '<circle cx="78" cy="' + (y + 10) + '" r="4.5" fill="#ff8fa3" opacity=".6"/><circle cx="122" cy="' + (y + 10) + '" r="4.5" fill="#ff8fa3" opacity=".6"/>'; break;
    case "goofy": s = eyeBall(88, y, 10, 4, 1) + eyeBall(112, y, 10, -4, 1) + mouth("grin", y + 13, mc) + '<rect x="96" y="' + (y + 11) + '" width="8" height="6" rx="1" fill="#fff"/>'; break;
    case "cool": s = shades(y) + mouth("smirk", y + 15, mc); break;
    case "smug": s = '<path d="M80 ' + (y - 1) + ' Q88 ' + (y - 5) + ' 96 ' + (y - 1) + ' M104 ' + (y - 1) + ' Q112 ' + (y - 5) + ' 120 ' + (y - 1) + '" stroke="' + INK + '" stroke-width="3.5" fill="none" stroke-linecap="round"/>' + eyeBall(88, y + 3, 6, 2, 0) + eyeBall(112, y + 3, 6, 2, 0) + mouth("smirk", y + 15, mc); break;
    default: if (b.eyes === "fierce" && !faceItem) { s = eyeBall(88, y + 1, 9, 1, 1) + eyeBall(112, y + 1, 9, -1, 1) + '<path d="M76 ' + (y - 14) + ' L97 ' + (y - 7) + ' M124 ' + (y - 14) + ' L103 ' + (y - 7) + '" stroke="' + INK + '" stroke-width="5" stroke-linecap="round"/>' + mouth("smirk", y + 15, mc); break; }
      s = (cool ? shades(y) : E()) + mouth("smile", y + 15, mc);
  }
  return s;
}
