    var r = b.getBoundingClientRect(), cx = r.left + r.width / 2, cy = r.top + r.height * 0.45;
    for (var i = 0; i < 10; i++) { var s = document.createElement("i"); s.className = "lvspark"; var a = Math.PI * 2 * i / 10; s.style.left = cx + "px"; s.style.top = cy + "px"; s.style.setProperty("--dx", Math.round(Math.cos(a) * 60) + "px"); s.style.setProperty("--dy", Math.round(Math.sin(a) * 60) + "px"); document.body.appendChild(s); setTimeout(function (n) { return function () { if (n.parentNode) n.parentNode.removeChild(n); }; }(s), 800); }
    var Q = LVB_QUIPS[key] || ["Nice!"], old = document.querySelector(".lvquip"); if (old) old.remove();
    var q = document.createElement("span"); q.className = "lvquip"; q.setAttribute("role", "status"); q.textContent = Q[Math.floor(Math.random() * Q.length)];
    q.style.top = Math.max(40, r.top - 8) + "px"; document.body.appendChild(q); var w = q.offsetWidth / 2 + 10; q.style.left = Math.max(w, Math.min(innerWidth - w, cx)) + "px";
