  var parts = t.replace(/([.;])\s+/g, "$1\u0001").split("\u0001"), hit = parts.filter(function (p) { var l = p.toLowerCase(); return names.some(function (n) { return n.length > 3 && new RegExp("\\b" + n.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(s|es)?\\b").test(l); }); });
