  var D = CL.dash[cid];
  if (!D) { CL.dash[cid] = { loading: true }; CL.db.collection("rosters").where("classIds", "array-contains", cid).limit(500).get().then(function (qs) { CL.dash[cid] = { students: qs.docs.map(function (d) { return d.data(); }) }; render(); }).catch(function () { CL.dash[cid] = { students: [] }; render(); }); }
  var st = (D && D.students) || [], asg = k.asg || [];
