/* disclosure: shown every time the app is opened (cold start, and coming back after the app was in the background);
   the button unlocks after 5 seconds */
var DISC_SECS = 5, DISC_AWAY = 15000;
function needDisc() { return !S.discOk && !window.__DRUGBUG_SKIP_DISC && S.view !== "legal"; }
function discView() {
  if (!S.discT0) S.discT0 = Date.now();
  var left = Math.max(0, DISC_SECS - Math.floor((Date.now() - S.discT0) / 1000));
  if (left > 0 && !S.discTimer) S.discTimer = setInterval(discTick, 250);
  return '<div class="gate disc" role="alertdialog" aria-labelledby="disch" aria-describedby="discb"><div class="glogo">' + bugSVG("sage") + '</div><h1 id="disch">Education only</h1>' +
    '<div id="discb" class="disctext"><p><strong>DrugBug is for education only. It is not to be used in patient care.</strong></p>' +
    '<p>Nothing in this app is medical advice, a treatment recommendation or a medical device. Doses, practice scenarios and every other tool are study material only. DrugBug never tells anyone to take, give or use any drug.</p>' +
    '<p>For real patients, always follow your protocols, medical direction, facility policy, the current FDA label and a licensed clinician. If you have a health question about yourself, ask your doctor or pharmacist. In an emergency, call 911.</p>' +
    '<p><strong>DrugBug is for adults 18 and older only.</strong></p></div>' +
    '<div class="actions"><button class="btn" id="discok" data-act="discok"' + (left > 0 ? ' disabled aria-disabled="true"' : '') + '>' + (left > 0 ? 'Please read (' + left + ')' : 'I understand') + '</button></div>' +
    '<p class="muted small">' + esc(NONAFF) + '</p></div>';
}
function discTick() {
  var left = Math.max(0, DISC_SECS - Math.floor((Date.now() - (S.discT0 || Date.now())) / 1000)), b = document.getElementById("discok");
  if (!b) { if (!needDisc()) { clearInterval(S.discTimer); S.discTimer = null; } return; }
  if (left > 0) { b.textContent = lang() === "es" ? "Lea por favor (" + left + ")" : "Please read (" + left + ")"; return; }
  clearInterval(S.discTimer); S.discTimer = null; b.disabled = false; b.removeAttribute("aria-disabled"); b.textContent = lang() === "es" ? "Entiendo" : "I understand";
}
function acceptDisc() {
  if (!S.discT0 || Date.now() - S.discT0 < DISC_SECS * 1000) return;
  S.discOk = true;
  if (S.discSheet && S.sheet && typeof sheet !== "undefined" && sheet) { sheet.hidden = false; app.setAttribute("aria-hidden", "true"); } S.discSheet = false;
  if (typeof muGesture === "function") muGesture();
  render(); window.scrollTo(0, 0);
  if (typeof wdwAuto === "function") setTimeout(wdwAuto, 700);
  if (typeof holOpenFx === "function") setTimeout(holOpenFx, 350);
}

document.addEventListener("visibilitychange", function () {
  if (document.hidden) { S.discAway = Date.now(); return; }
  if (S.discAway && Date.now() - S.discAway >= DISC_AWAY && S.discOk) { S.discOk = false; S.discT0 = 0; clearInterval(S.discTimer); S.discTimer = null; if (S.sheet && typeof sheet !== "undefined" && sheet) { sheet.hidden = true; S.discSheet = true; app.removeAttribute("aria-hidden"); } if (typeof closePrint === "function" && document.body.classList.contains("printing")) closePrint(); if (typeof closePaywall === "function") closePaywall(); if (typeof wdwClose === "function") wdwClose(); if (typeof evoClose === "function") evoClose(); if (typeof closeReport === "function") closeReport(); render(); window.scrollTo(0, 0); }
  S.discAway = 0;
});

