var PB_USES = [["aad", "Antibiotic-associated diarrhea"], ["cdiff", "C. difficile"], ["peds-diarrhea", "Children's acute diarrhea"], ["travel", "Travelers' diarrhea"], ["ibs", "IBS"], ["colic", "Infant colic"], ["nec", "Preterm infants (NEC)"], ["ibd", "Colitis, pouchitis, Crohn"], ["hpylori", "H. pylori treatment"], ["vaginal", "Vaginal and urinary health"], ["oral", "Mouth and throat"], ["allergy", "Eczema and allergy"], ["resp", "Colds and respiratory infections"], ["constipation", "Constipation"], ["mood", "Stress, mood and sleep"], ["metabolic", "Weight, glucose and lipids"], ["lactose", "Lactose digestion"], ["general", "General gut comfort"]];
var PB_USES_ES = { aad: "Diarrea por antibióticos", cdiff: "C. difficile", "peds-diarrhea": "Diarrea aguda en niños", travel: "Diarrea del viajero", ibs: "Síndrome de intestino irritable", colic: "Cólico del lactante", nec: "Bebés prematuros (ECN)", ibd: "Colitis, pouchitis, Crohn", hpylori: "Tratamiento de H. pylori", vaginal: "Salud vaginal y urinaria", oral: "Boca y garganta", allergy: "Eccema y alergia", resp: "Resfriados e infecciones respiratorias", constipation: "Estreñimiento", mood: "Estrés, ánimo y sueño", metabolic: "Peso, glucosa y lípidos", lactose: "Digestión de lactosa", general: "Comodidad digestiva general" };
var PB_EV = { strong: ["Stronger evidence", "Evidencia más sólida"], some: ["Some evidence", "Alguna evidencia"], mixed: ["Mixed results", "Resultados mixtos"], none: ["No benefit shown", "Sin beneficio demostrado"], early: ["Early research", "Investigación temprana"] };
