    while (i > 0) { var a = trail[i], b = trail[i - 1], L = Math.hypot(a.x - b.x, a.y - b.y); if (L >= d) { var f = L ? d / L : 0; return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f, a: Math.atan2(a.y - b.y, a.x - b.x) }; } d -= L; i--; }
    return { x: trail[0].x, y: trail[0].y, a: 0 };
