/* sounds (follow Settings → Sound effects) */
function gfxSnd(kind) {
  if (typeof SET !== "function" || !SET().sfx) return;
  try {
    var AC = window.AudioContext || window.webkitAudioContext; if (!AC) return;
    var c = SFX.ctx || (SFX.ctx = new AC()), t = c.currentTime;
    function tone(type, f0, f1, at, dur, v) { var o = c.createOscillator(), g = c.createGain(); o.type = type; o.frequency.setValueAtTime(f0, t + at); if (f1) o.frequency.exponentialRampToValueAtTime(f1, t + at + dur); g.gain.setValueAtTime(0.0001, t + at); g.gain.exponentialRampToValueAtTime(v || 0.15, t + at + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + at + dur); o.connect(g); g.connect(c.destination); o.start(t + at); o.stop(t + at + dur + 0.02); }
    function noise(at, dur, v, fq) { var n = c.sampleRate * dur, b = c.createBuffer(1, n, c.sampleRate), d = b.getChannelData(0); for (var i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n); var s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain(); s.buffer = b; f.type = "lowpass"; f.frequency.value = fq || 900; g.gain.value = v || 0.25; s.connect(f); f.connect(g); g.connect(c.destination); s.start(t + at); }
    if (kind === "pop") tone("sine", 520, 1100, 0, 0.09, 0.16);
    else if (kind === "chomp") { noise(0, 0.07, 0.35, 700); tone("square", 140, 70, 0, 0.08, 0.08); noise(0.1, 0.06, 0.3, 600); }
    else if (kind === "chirp") { tone("sine", 3200, 4200, 0, 0.04, 0.06); tone("sine", 3400, 4400, 0.07, 0.04, 0.06); }
    else if (kind === "buzz") { var o = c.createOscillator(), g = c.createGain(), l = c.createOscillator(), lg = c.createGain(); o.type = "sawtooth"; o.frequency.value = 190; l.frequency.value = 28; lg.gain.value = 25; l.connect(lg); lg.connect(o.frequency); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.06, t + 0.05); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.8); o.connect(g); g.connect(c.destination); o.start(t); l.start(t); o.stop(t + 0.85); l.stop(t + 0.85); }
    else if (kind === "burp") { tone("sawtooth", 110, 70, 0, 0.35, 0.12); noise(0, 0.3, 0.12, 300); }
    else if (kind === "whoosh") noise(0, 0.45, 0.2, 2400);
    else if (kind === "tick") tone("square", 1800, 0, 0, 0.03, 0.05);
    else if (kind === "win") [523, 659, 784, 1047].forEach(function (f, i) { tone("triangle", f, 0, i * 0.09, 0.18, 0.13); });
    else if (kind === "zip") tone("sine", 400, 1600, 0, 0.18, 0.08);
    else if (kind === "sparkle") [1568, 2093, 2637].forEach(function (f, i) { tone("sine", f, 0, i * 0.06, 0.12, 0.07); });
  } catch (e) {}
}

/* your own bug pops up and dances */
function gfxCheer() {
  if (typeof myBugArt !== "function") return;
  var e = gfxAdd('<div class="gfxcheer">' + myBugArt("gfxbug", "joy") + '<span class="gfxsay">Nice!</span></div>', "", 2600);
  gfxSnd("win");
}
/* "New best!" banner with falling leaf confetti */
function gfxBest(text) {
  gfxAdd('<div class="gfxbest">' + esc(text || "New best!") + '</div>', "", 2800);
  if (gfxReduce()) return;
  var cols = ["#22c55e", "#84cc16", "#16a34a", "#facc15", "#f97316"], html = "";
  for (var i = 0; i < 26; i++) html += '<i class="leaf" style="left:' + (Math.random() * 100).toFixed(1) + '%;animation-delay:' + (Math.random() * 0.8).toFixed(2) + 's;animation-duration:' + (1.8 + Math.random() * 1.4).toFixed(2) + 's;background:' + cols[i % cols.length] + ';--r:' + Math.round(Math.random() * 720 - 360) + 'deg"></i>';
  gfxAdd(html, "position:fixed;inset:0", 3600);
}
/* Memory: a matched card cracks like an egg and a tiny bug flutters out */
