  var y = 120 + Math.random() * (window.innerHeight * .5), W = window.innerWidth, ltr = Math.random() < .5;
  var d = gfxAdd('<div class="flap fast"' + (ltr ? "" : ' style="transform:scaleX(-1)"') + '>' + GFX_FLY + '</div>', "position:fixed;left:0;top:0", 1400);
