function openIdeas() { ID.open = { type: IDEA_TYPES[0], text: "" }; ID.sent = false; ID.err = ""; S.menu = false; drawIdeas(); idlg.hidden = false; var f = $("#idtext", idlg); if (f) f.focus(); }
